import { NgTemplateOutlet } from '@angular/common';
import { ChangeDetectionStrategy, Component, computed, effect, inject, input, numberAttribute, output, signal, TemplateRef, ViewEncapsulation } from '@angular/core';
import { MotionEvent, MotionOptions } from '@primeuix/motion';
import { SharedModule, ToastMessageOptions } from 'primeng/api';
import { BaseComponent } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { Check as CheckIcon } from '@primeicons/angular/check';
import { InfoCircle as InfoCircleIcon } from '@primeicons/angular/info-circle';
import { TimesCircle as TimesCircleIcon } from '@primeicons/angular/times-circle';
import { ExclamationTriangle as ExclamationTriangleIcon } from '@primeicons/angular/exclamation-triangle';
import { Times as TimesIcon } from '@primeicons/angular/times';
import { MotionModule } from 'primeng/motion';
import { ToastHeadlessTemplateContext, ToastItemCloseEvent, ToastMessageTemplateContext, ToastPassThrough } from 'primeng/types/toast';
import { ToastStyle } from './style/toaststyle';

const SWIPE_THRESHOLD = 50;
const VELOCITY_THRESHOLD = 0.11;
const SWIPE_OUT_DURATION = 500;

@Component({
    selector: 'p-toast-item',
    standalone: true,
    imports: [NgTemplateOutlet, CheckIcon, InfoCircleIcon, TimesCircleIcon, ExclamationTriangleIcon, TimesIcon, SharedModule, Bind, MotionModule],
    template: `
        <div
            #container
            [pMotion]="visible()"
            [pMotionAppear]="true"
            [pMotionOptions]="motionOptions()"
            (pMotionOnBeforeEnter)="onBeforeEnter($event)"
            (pMotionOnAfterEnter)="onAfterEnter()"
            (pMotionOnAfterLeave)="onAfterLeave($event)"
            [attr.id]="message()?.id"
            [pBind]="ptm('message')"
            [class]="cn(cx('message'), message()?.styleClass)"
            [style]="stackStyles()"
            (pointerdown)="onPointerDown($event)"
            (pointermove)="onPointerMove($event)"
            (pointerup)="onPointerUp()"
            (dragend)="onDragEnd()"
            role="alert"
            aria-live="assertive"
            aria-atomic="true"
            [attr.data-p]="dataP()"
            data-stack=""
            [attr.data-mounted]="dataMounted()"
            [attr.data-removed]="dataRemoved()"
            [attr.data-front]="dataFront()"
            [attr.data-expanded]="dataExpanded()"
            [attr.data-visible]="dataVisible()"
            [attr.data-swiping]="dataSwiping()"
            [attr.data-swiped]="dataSwiped()"
            [attr.data-swipe-out]="dataSwipeOut()"
            [attr.data-swipe-direction]="dataSwipeDirection()"
            [attr.data-dismissible]="dataDismissible()"
        >
            @if (headlessTemplate()) {
                <ng-container *ngTemplateOutlet="headlessTemplate(); context: headlessContext()"></ng-container>
            } @else {
                <div [pBind]="ptm('messageContent')" [class]="cn(cx('messageContent'), message()?.contentStyleClass)">
                    @if (!template()) {
                        @if (message()?.icon) {
                            <span [pBind]="ptm('messageIcon')" [class]="cn(cx('messageIcon'), message()?.icon)"></span>
                        } @else if (severityIcon()) {
                            @switch (severityIcon()) {
                                @case ('check') {
                                    <svg data-p-icon="check" [pBind]="ptm('messageIcon')" [class]="cx('messageIcon')" [attr.aria-hidden]="true" />
                                }
                                @case ('times-circle') {
                                    <svg data-p-icon="times-circle" [pBind]="ptm('messageIcon')" [class]="cx('messageIcon')" [attr.aria-hidden]="true" />
                                }
                                @case ('exclamation-triangle') {
                                    <svg data-p-icon="exclamation-triangle" [pBind]="ptm('messageIcon')" [class]="cx('messageIcon')" [attr.aria-hidden]="true" />
                                }
                                @case ('info-circle') {
                                    <svg data-p-icon="info-circle" [pBind]="ptm('messageIcon')" [class]="cx('messageIcon')" [attr.aria-hidden]="true" />
                                }
                            }
                        }
                        <div [pBind]="ptm('messageText')" [class]="cx('messageText')" [attr.data-p]="dataP()">
                            <div [pBind]="ptm('summary')" [class]="cx('summary')" [attr.data-p]="dataP()">
                                {{ message()?.summary }}
                            </div>
                            <div [pBind]="ptm('detail')" [class]="cx('detail')" [attr.data-p]="dataP()">{{ message()?.detail }}</div>
                        </div>
                    }
                    @if (template()) {
                        <ng-container *ngTemplateOutlet="template(); context: messageContext()"></ng-container>
                    }
                    @if (showCloseButton()) {
                        <div>
                            <button
                                [pBind]="ptm('closeButton')"
                                type="button"
                                [attr.class]="cx('closeButton')"
                                (click)="onCloseIconClick($event)"
                                (keydown.enter)="onCloseIconClick($event)"
                                [attr.aria-label]="closeAriaLabel"
                                autofocus
                                [attr.data-p]="dataP()"
                            >
                                @if (message()?.closeIcon) {
                                    <span [pBind]="ptm('closeIcon')" [class]="cn(cx('closeIcon'), message()?.closeIcon)"></span>
                                } @else {
                                    <svg [pBind]="ptm('closeIcon')" data-p-icon="times" [class]="cx('closeIcon')" [attr.aria-hidden]="true" />
                                }
                            </button>
                        </div>
                    }
                </div>
            }
        </div>
    `,
    encapsulation: ViewEncapsulation.None,
    changeDetection: ChangeDetectionStrategy.OnPush,
    providers: [ToastStyle]
})
export class ToastItem extends BaseComponent<ToastPassThrough> {
    /**
     * Message instance.
     * @group Props
     */
    message = input<ToastMessageOptions | null>();
    /**
     * Index of the message.
     * @group Props
     */
    index = input<number, unknown>(undefined, { transform: numberAttribute });
    /**
     * Life duration in milliseconds.
     * @group Props
     */
    life = input<number, unknown>(undefined, { transform: numberAttribute });
    /**
     * Custom message template.
     * @group Props
     */
    template = input<TemplateRef<ToastMessageTemplateContext>>();
    /**
     * Custom headless template.
     * @group Props
     */
    headlessTemplate = input<TemplateRef<ToastHeadlessTemplateContext>>();
    /**
     * The motion options.
     * @group Props
     */
    motionOptions = input<MotionOptions>();
    /**
     * Clear all trigger.
     * @group Props
     */
    clearAll = input<object | null>(null);
    /**
     * Whether the stack is expanded.
     * @group Props
     */
    stackExpanded = input(false);
    /**
     * Whether the toast container is currently hovered or focused.
     * @group Props
     */
    stackIsHovered = input(false);
    /**
     * Index of this toast in the stack.
     * @group Props
     */
    stackIndex = input(0, { transform: numberAttribute });
    /**
     * Total number of toasts in the stack.
     * @group Props
     */
    stackTotal = input(0, { transform: numberAttribute });
    /**
     * Cumulative offset for expanded state in pixels.
     * @group Props
     */
    stackOffset = input(0, { transform: numberAttribute });
    /**
     * Whether this toast is within the visible limit.
     * @group Props
     */
    stackIsVisible = input(false);
    /**
     * Whether the user is interacting with the toast container.
     * @group Props
     */
    stackIsInteracting = input(false);
    /**
     * Position of the toast container.
     * @group Props
     */
    position = input<string>('top-right');
    /**
     * Emits when animation starts.
     * @group Emits
     */
    onAnimationStart = output<HTMLElement>();
    /**
     * Emits when animation ends.
     * @group Emits
     */
    onAnimationEnd = output<HTMLElement>();
    /**
     * Emits when message is closed.
     * @group Emits
     */
    onClose = output<ToastItemCloseEvent>();
    /**
     * Emits when toast height is measured (for stack mode).
     * @group Emits
     */
    onHeightChange = output<{ index: number; height: number; removed?: boolean }>();

    _componentStyle = inject(ToastStyle);

    timeout: ReturnType<typeof setTimeout> | null = null;

    visible = signal<boolean | undefined>(undefined);

    showCloseButton = computed(() => this.message()?.closable !== false);

    private static readonly severityIcons: Record<string, string> = {
        success: 'check',
        info: 'info-circle',
        error: 'times-circle',
        warn: 'exclamation-triangle',
        secondary: 'info-circle',
        contrast: 'info-circle'
    };

    severityIcon = computed(() => ToastItem.severityIcons[this.message()?.severity as string] ?? null);

    private isDestroyed = false;

    mounted = signal(false);

    measuredHeight = signal(0);

    removed = signal(false);

    offsetBeforeRemove = signal(0);

    swiping = signal(false);

    isSwiped = signal(false);

    swipeOut = signal(false);

    swipeDirection = signal<'x' | 'y' | null>(null);

    swipeOutDirection = signal<'left' | 'right' | 'up' | 'down' | null>(null);

    swipeAmountX = signal(0);

    swipeAmountY = signal(0);

    pointerStartPosition: { x: number; y: number } | null = null;

    swipeStartTime = 0;

    dataMounted = computed(() => (this.mounted() ? '' : null));

    dataFront = computed(() => (this.stackIndex() === 0 ? '' : null));

    dataExpanded = computed(() => (this.stackExpanded() ? '' : null));

    dataVisible = computed(() => (this.stackIsVisible() ? '' : null));

    dataRemoved = computed(() => (this.removed() ? '' : null));

    dataSwiping = computed(() => (this.swiping() ? '' : null));

    dataSwiped = computed(() => (this.isSwiped() ? '' : null));

    dataSwipeOut = computed(() => (this.swipeOut() ? '' : null));

    dataSwipeDirection = computed(() => (this.swipeOutDirection() ? this.swipeOutDirection() : null));

    dataDismissible = computed(() => String(this.message()?.closable !== false));

    stackStyles = computed(() => {
        const idx = this.stackIndex();
        const total = this.stackTotal();
        return {
            '--px-toast-index': this.removed() ? this.stackIndex() : idx,
            '--px-toast-z-index': total - idx,
            '--px-initial-height': this.measuredHeight() + 'px',
            '--px-toast-offset': (this.removed() ? this.offsetBeforeRemove() : this.stackOffset()) + 'px',
            '--px-swipe-amount-x': this.swipeAmountX() + 'px',
            '--px-swipe-amount-y': this.swipeAmountY() + 'px',
            'z-index': total - idx
        };
    });

    constructor() {
        super();

        effect(() => {
            if (this.clearAll()) {
                this.visible.set(false);
            }
        });

        effect(() => {
            // Pause auto-dismiss only while hovered/focused, interacting or swiping — not in expanded mode
            // (expanded just lays the stack out open; toasts still dismiss on their own). Mirrors React's useToast.
            const hovered = this.stackIsHovered();
            const interacting = this.stackIsInteracting();
            const swiping = this.swiping();

            if (hovered || interacting || swiping) {
                this.pauseStackTimer();
            } else {
                this.startStackTimer();
            }
        });
    }

    onBeforeEnter(event: MotionEvent) {
        this.onAnimationStart.emit(event.element as HTMLElement);
    }

    onAfterEnter() {
        this.measureStackHeight();
    }

    onAfterLeave(event: MotionEvent) {
        if (!this.visible() && !this.isDestroyed) {
            this.onClose.emit({
                index: this.index() as number,
                message: this.message() as ToastMessageOptions
            });

            if (!this.isDestroyed) {
                this.onAnimationEnd.emit(event.element as HTMLElement);
            }
        }
    }

    onAfterViewInit() {
        this.visible.set(true);
        this.measureStackHeight();
    }

    private measureStackHeight() {
        if (this.mounted()) return;
        const el = this.el.nativeElement.querySelector('[data-stack]') as HTMLElement;
        if (!el) return;
        const orig = el.style.height;
        el.style.height = 'auto';
        const height = el.getBoundingClientRect().height;
        el.style.height = orig;
        this.measuredHeight.set(height);
        this.onHeightChange.emit({ index: this.index() as number, height });
        this.mounted.set(true);
    }

    private remainingTime = 0;

    private timerStartTime = 0;

    startStackTimer() {
        const msg = this.message();
        if (msg?.sticky) return;
        this.clearTimeout();
        if (this.remainingTime <= 0) {
            this.remainingTime = msg?.life || this.life() || 3000;
        }
        this.timerStartTime = Date.now();
        this.timeout = setTimeout(() => {
            this.handleFocusOnRemove();
            this.closeStack();
        }, this.remainingTime);
    }

    pauseStackTimer() {
        if (this.timerStartTime > 0 && this.timeout) {
            const elapsed = Date.now() - this.timerStartTime;
            this.remainingTime = Math.max(0, this.remainingTime - elapsed);
        }
        this.clearTimeout();
    }

    clearTimeout() {
        if (this.timeout) {
            clearTimeout(this.timeout);
            this.timeout = null;
        }
    }

    onCloseIconClick = (event?: Event) => {
        this.clearTimeout();

        this.handleFocusOnRemove();
        this.closeStack();

        event?.preventDefault();
    };

    private closeStack() {
        this.markRemoved();
        this.visible.set(false);
    }

    private isDismissible(): boolean {
        return this.message()?.closable !== false;
    }

    private markRemoved() {
        // A pending close/transition callback can reach this after teardown; bail so we don't
        // emit on a destroyed OutputRef.
        if (this.isDestroyed) return;
        this.offsetBeforeRemove.set(this.stackOffset());
        this.removed.set(true);
        this.onHeightChange.emit({ index: this.index() as number, height: 0, removed: true });
    }

    onPointerDown = (event: PointerEvent) => {
        if (event.button !== 0) return;
        if (!this.isDismissible()) return;

        this.swipeStartTime = Date.now();
        this.offsetBeforeRemove.set(this.stackOffset());

        try {
            (event.target as HTMLElement).setPointerCapture(event.pointerId);
        } catch (_) {
            // ignore — some elements don't support pointer capture
        }

        this.swiping.set(true);
        this.pointerStartPosition = { x: event.clientX, y: event.clientY };
    };

    onPointerMove = (event: PointerEvent) => {
        if (!this.pointerStartPosition || !this.isDismissible()) return;
        if ((window.getSelection()?.toString().length ?? 0) > 0) return;

        const yDelta = event.clientY - this.pointerStartPosition.y;
        const xDelta = event.clientX - this.pointerStartPosition.x;
        const isRealSwipe = Math.abs(xDelta) > 1 || Math.abs(yDelta) > 1;

        const positionParts = (this.position() ?? 'top-right').split('-');
        const side = positionParts[0];
        const align = positionParts[1];

        if (!this.swipeDirection() && isRealSwipe) {
            this.swipeDirection.set(Math.abs(xDelta) > Math.abs(yDelta) ? 'x' : 'y');
        }

        let nextX = 0;
        let nextY = 0;

        if (this.swipeDirection() === 'x') {
            const naturalDirection = (align === 'left' && xDelta < 0) || (align === 'right' && xDelta > 0);
            nextX = naturalDirection ? xDelta : this.applyDampening(xDelta);
        } else if (this.swipeDirection() === 'y') {
            const naturalDirection = (side === 'top' && yDelta < 0) || (side === 'bottom' && yDelta > 0);
            nextY = naturalDirection ? yDelta : this.applyDampening(yDelta);
        }

        if (Math.abs(nextX) > 0 || Math.abs(nextY) > 0) {
            this.isSwiped.set(true);
        }

        this.swipeAmountX.set(nextX);
        this.swipeAmountY.set(nextY);
    };

    onPointerUp = () => {
        if (this.swipeOut() || !this.isDismissible()) return;

        this.swiping.set(false);
        this.pointerStartPosition = null;

        const swipeAmount = this.swipeDirection() === 'x' ? this.swipeAmountX() : this.swipeAmountY();
        const elapsed = Date.now() - (this.swipeStartTime || Date.now());
        const velocity = elapsed > 0 ? Math.abs(swipeAmount) / elapsed : 0;

        if (Math.abs(swipeAmount) >= SWIPE_THRESHOLD || velocity > VELOCITY_THRESHOLD) {
            this.offsetBeforeRemove.set(this.stackOffset());

            if (this.swipeDirection() === 'x') {
                this.swipeOutDirection.set(this.swipeAmountX() > 0 ? 'right' : 'left');
            } else {
                this.swipeOutDirection.set(this.swipeAmountY() > 0 ? 'down' : 'up');
            }

            this.swipeOut.set(true);
            this.markRemoved();
            this.scheduleSwipeOutClose();

            return;
        }

        this.swipeAmountX.set(0);
        this.swipeAmountY.set(0);
        this.isSwiped.set(false);
        this.swipeDirection.set(null);
    };

    onDragEnd = () => {
        this.swiping.set(false);
        this.swipeDirection.set(null);
        this.pointerStartPosition = null;
    };

    private applyDampening(delta: number): number {
        const factor = Math.abs(delta) / 20;
        const dampenedDelta = delta * (1 / (1.5 + factor));
        return Math.abs(dampenedDelta) < Math.abs(delta) ? dampenedDelta : delta;
    }

    private scheduleSwipeOutClose() {
        this.clearTimeout();
        this.timeout = setTimeout(() => {
            this.visible.set(false);
        }, SWIPE_OUT_DURATION);
    }

    private handleFocusOnRemove() {
        const el = this.el.nativeElement;
        const activeEl = this.document.activeElement as HTMLElement;
        if (!el?.contains(activeEl)) return;
        const next = el.nextElementSibling?.querySelector('[data-pc-section="closebutton"]') as HTMLElement;
        const prev = el.previousElementSibling?.querySelector('[data-pc-section="closebutton"]') as HTMLElement;
        requestAnimationFrame(() => {
            if (next) next.focus({ preventScroll: true });
            else if (prev) prev.focus({ preventScroll: true });
        });
    }

    get closeAriaLabel() {
        return this.config.translation.aria ? this.config.translation.aria.close : undefined;
    }

    onDestroy() {
        this.isDestroyed = true;
        this.clearTimeout();
        this.visible.set(false);
    }

    headlessContext = computed<ToastHeadlessTemplateContext>(() => ({
        $implicit: this.message(),
        closeFn: this.onCloseIconClick
    }));

    messageContext = computed<ToastMessageTemplateContext>(() => ({
        $implicit: this.message(),
        closeFn: this.onCloseIconClick
    }));

    dataP = computed(() => {
        const msg = this.message();
        return this.cn({
            [msg?.severity as string]: msg?.severity
        });
    });
}
